/*selectBuyerWmGrWarehousingRegList*/ SELECT S.PO_NO -- 1 , S.INV_NO -- 2 , S.BUYER_ITEM_NO -- 3 , S.REF_PR_NO -- 4 , S.DESCRIPTION -- 5 , S.SPECIFICATION -- 6 , S.PO_QTY -- 7 , S.UNIT_MEASURE -- 8 , S.PO_CREATE_DATE -- 9 , S.UNIT_PRICE -- 10 , S.PO_AMT -- 11 , S.INV_QTY -- 12 , S.GR_QTY -- 13 , S.AVAIL_GR_QTY , S.PO_CREATOR -- 14 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','코리아이플랫폼(주)',S.AGENT_NAME) AS AGENT_NAME -- 15 , S.REQ_DEPT_NAME -- 16 , S.BUYER -- 17 , S.SELLER -- 18 , S.PO_SEQ -- 19 , S.INV_SEQ -- 20 , S.AGENT -- 21 , S.AGENT_PRICE -- 22 , S.BYIT_COMORG_CODE -- 23 , S.CONTRACT_NO -- 24 , S.CONTRACT_SEQ -- 25 , S.REQ_DEPT -- 26 , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','KRKORE0001',S.AGENT) AS AGENT_CODE -- 27 , S.WAREHOUSE_CODE -- 28 , S.PURCHASER_ID -- 29 , (SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_USE_FLAG -- 30 , (SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_CONFIRM_NO -- 31 , S.PX_NO , '0' AS TEMP_GR_QTY , S.RECV_FLAG , S.PCO_REF_PR_NO , S.PCO_LEGACY_PO_NO , S.ADD_USER_NAME , S.SIZE_QTY , S.SIZE_LEN , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE =S.BUYER) COM_NAME_LOC , S.AUTO_GR_FLAG , S.IMAGE_KEY_SIGN , S.IMAGE_KEY_INV , S.PR_USER_NAME , S.SND_CHK , S.CATEG_NAME , S.MAKER_NAME , S.ORIGIN_NAME , S.PO_TTL_AMT , S.CUR , S.PRE_GR_YN , S.FAST_PO_YN , S.PR_NO , S.PR_SEQ , S.RD_DATE , S.CD_DATE , S.STATUS_TEXT , S.INVOICE_DATE , '' AS DELIVERY_PERSON_NAME , '' AS DELIVERY_PERSON_PHONE , '' AS DELIVERY_CAR_NO , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = S.PARCEL_COM_CODE) AS PARCEL_COM_NAME , S.PARCEL_INV_NO , S.ADD_USER_TEL , TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI') AS TODAY_DATE , S.ADD_USER_NAME_ENG , S.ADD_USER_EMAIL , '1052552' AS ASN_VENDOR_CODE , (CASE WHEN TRIM(S.PARCEL_INFO) IS NOT NULL THEN '택배' ELSE ' ' END) AS PARCEL_INFO , S.GR_LOCK_MONTH FROM ( SELECT PODT.PO_NO , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) AS INV_NO , PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO , PODT.REF_PR_NO||DECODE(PODT.BUYER,'KRDAEW0016','-'||TO_NUMBER(PODT.LEGACY_PO_SEQ),'') AS REF_PR_NO , PODT.DESCRIPTION AS DESCRIPTION , PODT.SPECIFICATION AS SPECIFICATION , PODT.UNIT_PRICE AS UNIT_PRICE , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) * PODT.UNIT_PRICE AS PO_AMT , PODT.UNIT_MEASURE AS UNIT_MEASURE , POHD.PO_CREATE_DATE , PODT.ITEM_QTY AS PO_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) AS INV_QTY , NVL(PODT.GR_QTY,0) GR_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY- NVL(IV.GR_QTY,0) ,WMS.INV_QTY- NVL(WMS.BUYER_GR_QTY,0)) AS AVAIL_GR_QTY -- 입고가능수량 , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = DECODE(PODT.BUYER,'KRDUPO0001',PR.ADD_USER_ID,PR.PURCHASER_ID)) AS PO_CREATOR , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT AND STATUS !='D') AS AGENT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'C001' AND CODE = PR.REQ_DEPT) AS REQ_DEPT_NAME , PODT.BUYER , DECODE(PODT.PROCESS_TYPE,'0',IV.SELLER, WMS.SELLER ) AS SELLER , PODT.PO_SEQ , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_SEQ, WMS.INV_SEQ ) AS INV_SEQ , POHD.AGENT , PODT.AGENT_PRICE , PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE , PODT.CONTRACT_NO AS CONTRACT_NO , PODT.CONTRACT_SEQ AS CONTRACT_SEQ , PR.REQ_DEPT AS REQ_DEPT , DECODE(PODT.PROCESS_TYPE,'0','',WMS.WAREHOUSE_CODE) AS WAREHOUSE_CODE , POHD.PURCHASER_ID AS PURCHASER_ID , PR.PR_NO , PR.REF_NO AS PX_NO , PR.RECV_FLAG , PODT.REF_PR_NO AS PCO_REF_PR_NO , PODT.LEGACY_PO_NO AS PCO_LEGACY_PO_NO , PR.ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PR.ADD_USER_ID) AS PR_USER_NAME , NVL(BUYER.AUTO_GR_FLAG, 'N') AS AUTO_GR_FLAG , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_SIGN, WMS.IMAGE_KEY_SIGN) AS IMAGE_KEY_SIGN , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_INV, WMS.IMAGE_KEY_INV) AS IMAGE_KEY_INV , DECODE(PODT.PROCESS_TYPE,'0',IV.SND_CHK ,WMS.SND_CHK) AS SND_CHK , (SELECT CATEG_NAME FROM ICOMBYCA WHERE COM_CODE = PODT.BYIT_COMORG_CODE AND STD_CATEG_ID = PODT.CATEG_ID) AS CATEG_NAME , PODT.MAKER_NAME , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME , PODT.ITEM_QTY * PODT.UNIT_PRICE AS PO_TTL_AMT , POHD.CUR , DECODE(POHD.DOC_TYPE, 'S', 'Y', 'N') AS PRE_GR_YN , DECODE(POHD.DOC_TYPE, 'F', 'Y', 'N') AS FAST_PO_YN , PR.PR_SEQ , PR.RD_DATE , CASE WHEN PODT.PROCESS_TYPE = '0' THEN ( SELECT MAX(DS_DATE) FROM ICOMPORS WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND DS_DATE = PODT.DS_DATE AND STATUS != 'D' ) ELSE (SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS != 'D') END AS CD_DATE , F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 1) AS STATUS_TEXT , (DECODE(PODT.PROCESS_TYPE,'0', (SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <>'D'), (SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D')) ) AS INVOICE_DATE , IVHD.PARCEL_COM_CODE , IVHD.PARCEL_INV_NO , PR.ADD_USER_TEL , (SELECT USER_NAME_ENG FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_NAME_ENG , (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_EMAIL , DECODE(PODT.PROCESS_TYPE, '0', IVHD.PARCEL_INV_NO, WMS.DELIVERY_NO) AS PARCEL_INFO , (SELECT MAX(CODE) FROM ICOMCOD2 WHERE TYPE = 'NOGR' AND COMPANY_CODE = PODT.BUYER AND FLAG = 'Y') AS GR_LOCK_MONTH FROM ICOMPOHD POHD, ICOMPODT PODT ,ICOMPRDT PR , ICOMIVDT IV, WMSIVDT WMS, KEP_BUYER_FLAG BUYER, ICOMIVHD IVHD WHERE POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PODT.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND PODT.BUYER = #{st_com_code}
AND PODT.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND PODT.BUYER = #{st_com_code}
AND PODT.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND PODT.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND (UPPER( PR.BUYER_ITEM_NO) LIKE UPPER(#{st_buyer_item_no}||'%') OR .BUYER_ITEM_NO IN (SELECT DISTINCT BUYER_ITEM_NO FROM ICOMCQDT CQDT WHERE CQDT.BUYER = PODT.BUYER AND CQDT.STATUS <> 'D' AND CQDT.ITEM_NO LIKE UPPER('#{st_buyer_item_no}||'%')))
AND PR.ADD_USER_ID = #{st_change_user_id}
AND DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) LIKE '%'||UPPER(#{st_search_no})||'%'
AND PODT.PO_NO LIKE '%'||UPPER(#{st_search_no})||'%'
AND PODT.DESCRIPTION LIKE '%'||UPPER(#{st_search_no})||'%'
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID = #{st_po_user_id}
AND PR.REQ_DEPT = #{st_req_dept_code}
AND PODT.IV_QTY = PODT.DI_QTY
AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.STATUS <> 'D' AND PODT.ITEM_QTY <> NVL(PODT.GR_QTY, 0) AND PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.STATUS <> 'D' AND IV.BUYER = IVHD.BUYER AND IV.INV_NO = IVHD.INV_NO AND PODT.BUYER = PR.BUYER AND PODT.PR_NO = PR.PR_NO AND PODT.PR_SEQ = PR.PR_SEQ AND PR.STATUS <> 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ = WMS.S_INV_SEQ(+) AND PODT.BUYER = BUYER.COM_CODE(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) IS NOT NULL AND DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.GR_QTY,0), NVL(WMS.BUYER_GR_QTY,0)) <> DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.INV_QTY,0), NVL(WMS.INV_QTY,0)) ORDER BY PO_NO, INV_NO, INV_SEQ ) S

/*getBuyerWmGrWarehousingRegList_v2*/ SELECT S.PO_NO -- 1 , S.INV_NO -- 2 , S.BUYER_ITEM_NO -- 3 , S.REF_PR_NO -- 4 , S.DESCRIPTION -- 5 , S.SPECIFICATION -- 6 , S.PO_QTY -- 7 , S.UNIT_MEASURE -- 8 , S.PO_CREATE_DATE -- 9 , S.UNIT_PRICE -- 10 , S.PO_AMT -- 11 , S.INV_QTY -- 12 , S.GR_QTY -- 13 , S.AVAIL_GR_QTY , S.PO_CREATOR -- 14 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','코리아이플랫폼(주)',S.AGENT_NAME) AS AGENT_NAME -- 15 , S.REQ_DEPT_NAME -- 16 , S.BUYER -- 17 , S.SELLER -- 18 , S.PO_SEQ -- 19 , S.INV_SEQ -- 20 , S.AGENT -- 21 , S.AGENT_PRICE -- 22 , S.BYIT_COMORG_CODE -- 23 , S.CONTRACT_NO -- 24 , S.CONTRACT_SEQ -- 25 , S.REQ_DEPT -- 26 , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','KRKORE0001',S.AGENT) AS AGENT_CODE -- 27 , S.WAREHOUSE_CODE -- 28 , S.PURCHASER_ID -- 29 , (SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_USE_FLAG -- 30 , (SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_CONFIRM_NO -- 31 , S.PX_NO , '0' AS TEMP_GR_QTY , S.RECV_FLAG , S.PCO_REF_PR_NO , S.PCO_LEGACY_PO_NO , S.ADD_USER_NAME , S.SIZE_QTY , S.SIZE_LEN , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE =S.BUYER) COM_NAME_LOC , S.AUTO_GR_FLAG , S.IMAGE_KEY_SIGN , S.IMAGE_KEY_INV , S.PR_USER_NAME , S.SND_CHK , S.CATEG_NAME , S.MAKER_NAME , S.ORIGIN_NAME , S.PO_TTL_AMT , S.CUR , S.PRE_GR_YN , S.FAST_PO_YN , S.PR_NO , S.PR_SEQ , S.RD_DATE , S.CD_DATE , S.STATUS_TEXT , S.INVOICE_DATE , '' AS DELIVERY_PERSON_NAME , '' AS DELIVERY_PERSON_PHONE , '' AS DELIVERY_CAR_NO , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = S.PARCEL_COM_CODE) AS PARCEL_COM_NAME , S.PARCEL_INV_NO , S.ADD_USER_TEL , TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI') AS TODAY_DATE , S.ADD_USER_NAME_ENG , S.ADD_USER_EMAIL , '1052552' AS ASN_VENDOR_CODE , (CASE WHEN TRIM(S.PARCEL_INFO) IS NOT NULL THEN '택배' ELSE ' ' END) AS PARCEL_INFO , S.GR_LOCK_MONTH , S.GW_NO , S.PO_CREATE_DEPT_NAME , S.PR_CHANGE_DATE , S.PH_REMARK , S.BUDGET_DEPT , S.ACCOUNT_NAME FROM ( SELECT PODT.PO_NO , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) AS INV_NO , PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO , PODT.REF_PR_NO||DECODE(PODT.BUYER,'KRDAEW0016','-'||TO_NUMBER(PODT.LEGACY_PO_SEQ),'') AS REF_PR_NO , PODT.DESCRIPTION AS DESCRIPTION , PODT.SPECIFICATION AS SPECIFICATION , PODT.UNIT_PRICE AS UNIT_PRICE , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) * PODT.UNIT_PRICE AS PO_AMT , PODT.UNIT_MEASURE AS UNIT_MEASURE , POHD.PO_CREATE_DATE , PODT.ITEM_QTY AS PO_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) AS INV_QTY , NVL(PODT.GR_QTY,0) GR_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY- NVL(IV.GR_QTY,0) ,WMS.INV_QTY- NVL(WMS.BUYER_GR_QTY,0)) AS AVAIL_GR_QTY -- 입고가능수량 , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = DECODE(PODT.BUYER,'KRDUPO0001',PR.ADD_USER_ID,PR.PURCHASER_ID)) AS PO_CREATOR , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT AND STATUS !='D') AS AGENT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'C001' AND CODE = PR.REQ_DEPT) AS REQ_DEPT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.PURCHASER_DEPT AND TYPE = 'C001') AS PO_CREATE_DEPT_NAME , PODT.BUYER , DECODE(PODT.PROCESS_TYPE,'0',IV.SELLER, WMS.SELLER ) AS SELLER , PODT.PO_SEQ , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_SEQ, WMS.INV_SEQ ) AS INV_SEQ , POHD.AGENT , PODT.AGENT_PRICE , PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE , PODT.CONTRACT_NO AS CONTRACT_NO , PODT.CONTRACT_SEQ AS CONTRACT_SEQ , PR.REQ_DEPT AS REQ_DEPT , DECODE(PODT.PROCESS_TYPE,'0','',WMS.WAREHOUSE_CODE) AS WAREHOUSE_CODE , POHD.PURCHASER_ID AS PURCHASER_ID , PR.PR_NO , PR.REF_NO AS PX_NO , PR.RECV_FLAG , PODT.REF_PR_NO AS PCO_REF_PR_NO , PODT.LEGACY_PO_NO AS PCO_LEGACY_PO_NO , PR.ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PR.ADD_USER_ID) AS PR_USER_NAME , NVL(BUYER.AUTO_GR_FLAG, 'N') AS AUTO_GR_FLAG , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_SIGN, WMS.IMAGE_KEY_SIGN) AS IMAGE_KEY_SIGN , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_INV, WMS.IMAGE_KEY_INV) AS IMAGE_KEY_INV , DECODE(PODT.PROCESS_TYPE,'0',IV.SND_CHK ,WMS.SND_CHK) AS SND_CHK , (SELECT CATEG_NAME FROM ICOMBYCA WHERE COM_CODE = PODT.BYIT_COMORG_CODE AND STD_CATEG_ID = PODT.CATEG_ID) AS CATEG_NAME , PODT.MAKER_NAME , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME , PODT.ITEM_QTY * PODT.UNIT_PRICE AS PO_TTL_AMT , POHD.CUR , DECODE(POHD.DOC_TYPE, 'S', 'Y', 'N') AS PRE_GR_YN , DECODE(POHD.DOC_TYPE, 'F', 'Y', 'N') AS FAST_PO_YN , PR.PR_SEQ , PR.RD_DATE , CASE WHEN PODT.PROCESS_TYPE = '0' THEN ( SELECT MAX(DS_DATE) FROM ICOMPORS WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND DS_DATE = PODT.DS_DATE AND STATUS != 'D' ) ELSE (SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS != 'D') END AS CD_DATE , F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 1) AS STATUS_TEXT , (DECODE(PODT.PROCESS_TYPE,'0', (SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <>'D'), (SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D')) ) AS INVOICE_DATE , IVHD.PARCEL_COM_CODE , IVHD.PARCEL_INV_NO , PR.ADD_USER_TEL , (SELECT MAX(TARGET) FROM ICOMTRGW WHERE COM_CODE = PR.BUYER AND DOC_NAME = 'PR' AND KEY_1 = PR.PR_NO) AS GW_NO , (SELECT USER_NAME_ENG FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_NAME_ENG , (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_EMAIL , DECODE(PODT.PROCESS_TYPE, '0', IVHD.PARCEL_INV_NO, WMS.DELIVERY_NO) AS PARCEL_INFO , (SELECT MAX(CODE) FROM ICOMCOD2 WHERE TYPE = 'NOGR' AND COMPANY_CODE = PODT.BUYER AND FLAG = 'Y') AS GR_LOCK_MONTH , PR.CHANGE_DATE AS PR_CHANGE_DATE , POHD.PO_REMARK AS PH_REMARK , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'Z014' AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_NAME FROM ICOMPOHD POHD, ICOMPODT PODT ,ICOMPRDT PR , ICOMIVDT IV, WMSIVDT WMS, KEP_BUYER_FLAG BUYER, ICOMIVHD IVHD WHERE 1=1
AND PODT.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND PODT.BUYER = #{st_com_code}
AND PODT.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND PODT.BUYER = #{st_com_code}
AND PR.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND POHD.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PODT.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND UPPER(PODT.DESCRIPTION) LIKE UPPER('%'||#{st_search_no2}||'%')
AND UPPER( PODT.BUYER_ITEM_NO) LIKE UPPER('%'||#{st_search_no2}||'%')
AND UPPER(PODT.SPECIFICATION) LIKE UPPER('%'||#{st_search_no2}||'%')
AND DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) LIKE '%'||UPPER(#{st_search_no})||'%'
AND PR.PR_NO LIKE '%'||UPPER(#{st_search_no})||'%'
AND PODT.PO_NO LIKE '%'||UPPER(#{st_search_no})||'%'
AND PR.ADD_USER_ID = #{st_po_user_id}
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y'))
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y'))
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y'))
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y'))
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND PODT.IV_QTY = PODT.DI_QTY
AND PODT.IV_QTY <> PODT.DI_QTY
AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.STATUS <> 'D' AND PODT.ITEM_QTY <> NVL(PODT.GR_QTY, 0) AND PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.STATUS <> 'D' AND IV.BUYER = IVHD.BUYER AND IV.INV_NO = IVHD.INV_NO AND PODT.BUYER = PR.BUYER AND PODT.PR_NO = PR.PR_NO AND PODT.PR_SEQ = PR.PR_SEQ AND PR.STATUS <> 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ = WMS.S_INV_SEQ(+) AND PODT.BUYER = BUYER.COM_CODE(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) IS NOT NULL AND DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.GR_QTY,0), NVL(WMS.BUYER_GR_QTY,0)) <> DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.INV_QTY,0), NVL(WMS.INV_QTY,0)) ORDER BY PO_NO, INV_NO, INV_SEQ ) S

/*getBuyerWmGrWarehousingRegList_v3*/ SELECT S.PO_NO -- 1 , S.INV_NO -- 2 , S.BUYER_ITEM_NO -- 3 , S.REF_PR_NO -- 4 , S.DESCRIPTION -- 5 , S.SPECIFICATION -- 6 , S.PO_QTY -- 7 , S.UNIT_MEASURE -- 8 , S.PO_CREATE_DATE -- 9 , S.UNIT_PRICE -- 10 , S.PO_AMT -- 11 , S.INV_QTY -- 12 , S.GR_QTY -- 13 , S.AVAIL_GR_QTY , S.PO_CREATOR -- 14 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','코리아이플랫폼(주)',S.AGENT_NAME) AS AGENT_NAME -- 15 , S.REQ_DEPT_NAME -- 16 , S.BUYER -- 17 , S.SELLER -- 18 , S.PO_SEQ -- 19 , S.INV_SEQ -- 20 , S.AGENT -- 21 , S.AGENT_PRICE -- 22 , S.BYIT_COMORG_CODE -- 23 , S.CONTRACT_NO -- 24 , S.CONTRACT_SEQ -- 25 , S.REQ_DEPT -- 26 , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = #{st_com_code}),'N','KRKORE0001',S.AGENT) AS AGENT_CODE -- 27 , S.WAREHOUSE_CODE -- 28 , S.PURCHASER_ID -- 29 , (SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_USE_FLAG -- 30 , (SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_CONFIRM_NO -- 31 , S.PX_NO , '0' AS TEMP_GR_QTY , S.RECV_FLAG , S.PCO_REF_PR_NO , S.PCO_LEGACY_PO_NO , S.ADD_USER_NAME , S.SIZE_QTY , S.SIZE_LEN , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE =S.BUYER) COM_NAME_LOC , S.AUTO_GR_FLAG , S.IMAGE_KEY_SIGN , S.IMAGE_KEY_INV , S.PR_USER_NAME , S.SND_CHK , S.CATEG_NAME , S.MAKER_NAME , S.ORIGIN_NAME , S.PO_TTL_AMT , S.CUR , S.PRE_GR_YN , S.FAST_PO_YN , S.PR_NO , S.PR_SEQ , S.RD_DATE , S.CD_DATE , S.STATUS_TEXT , S.INVOICE_DATE , '' AS DELIVERY_PERSON_NAME , '' AS DELIVERY_PERSON_PHONE , '' AS DELIVERY_CAR_NO , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = S.PARCEL_COM_CODE) AS PARCEL_COM_NAME , S.PARCEL_INV_NO , S.ADD_USER_TEL , TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI') AS TODAY_DATE , S.ADD_USER_NAME_ENG , S.ADD_USER_EMAIL , '1052552' AS ASN_VENDOR_CODE , (CASE WHEN TRIM(S.PARCEL_INFO) IS NOT NULL THEN '택배' ELSE ' ' END) AS PARCEL_INFO , S.GR_LOCK_MONTH , S.GW_NO , S.PO_CREATE_DEPT_NAME , S.PR_CHANGE_DATE , S.PH_REMARK , S.BUDGET_DEPT , S.ACCOUNT_NAME , S.DELIVERY_DATE FROM ( SELECT PODT.PO_NO , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) AS INV_NO , PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO , PODT.REF_PR_NO||DECODE(PODT.BUYER,'KRDAEW0016','-'||TO_NUMBER(PODT.LEGACY_PO_SEQ),'') AS REF_PR_NO , PODT.DESCRIPTION AS DESCRIPTION , PODT.SPECIFICATION AS SPECIFICATION , PODT.UNIT_PRICE AS UNIT_PRICE , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) * PODT.UNIT_PRICE AS PO_AMT , PODT.UNIT_MEASURE AS UNIT_MEASURE , POHD.PO_CREATE_DATE , PODT.ITEM_QTY AS PO_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY, WMS.INV_QTY ) AS INV_QTY , NVL(PODT.GR_QTY,0) GR_QTY , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_QTY- NVL(IV.GR_QTY,0) ,WMS.INV_QTY- NVL(WMS.BUYER_GR_QTY,0)) AS AVAIL_GR_QTY -- 입고가능수량 , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = DECODE(PODT.BUYER,'KRDUPO0001',PR.ADD_USER_ID,PR.PURCHASER_ID)) AS PO_CREATOR , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT AND STATUS !='D') AS AGENT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'C001' AND CODE = PR.REQ_DEPT) AS REQ_DEPT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.PURCHASER_DEPT AND TYPE = 'C001') AS PO_CREATE_DEPT_NAME , PODT.BUYER , DECODE(PODT.PROCESS_TYPE,'0',IV.SELLER, WMS.SELLER ) AS SELLER , PODT.PO_SEQ , DECODE(PODT.PROCESS_TYPE,'0',IV.INV_SEQ, WMS.INV_SEQ ) AS INV_SEQ , POHD.AGENT , PODT.AGENT_PRICE , PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE , PODT.CONTRACT_NO AS CONTRACT_NO , PODT.CONTRACT_SEQ AS CONTRACT_SEQ , PR.REQ_DEPT AS REQ_DEPT , DECODE(PODT.PROCESS_TYPE,'0','',WMS.WAREHOUSE_CODE) AS WAREHOUSE_CODE , POHD.PURCHASER_ID AS PURCHASER_ID , PR.PR_NO , PR.REF_NO AS PX_NO , PR.RECV_FLAG , PODT.REF_PR_NO AS PCO_REF_PR_NO , PODT.LEGACY_PO_NO AS PCO_LEGACY_PO_NO , PR.ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PR.ADD_USER_ID) AS PR_USER_NAME , NVL(BUYER.AUTO_GR_FLAG, 'N') AS AUTO_GR_FLAG , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_SIGN, WMS.IMAGE_KEY_SIGN) AS IMAGE_KEY_SIGN , DECODE(PODT.PROCESS_TYPE, '0', IVHD.IMAGE_KEY_INV, WMS.IMAGE_KEY_INV) AS IMAGE_KEY_INV , DECODE(PODT.PROCESS_TYPE,'0',IV.SND_CHK ,WMS.SND_CHK) AS SND_CHK , (SELECT CATEG_NAME FROM ICOMBYCA WHERE COM_CODE = PODT.BYIT_COMORG_CODE AND STD_CATEG_ID = PODT.CATEG_ID) AS CATEG_NAME , PODT.MAKER_NAME , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PODT.ORIGIN_CODE) AS ORIGIN_NAME , PODT.ITEM_QTY * PODT.UNIT_PRICE AS PO_TTL_AMT , POHD.CUR , DECODE(POHD.DOC_TYPE, 'S', 'Y', 'N') AS PRE_GR_YN , DECODE(POHD.DOC_TYPE, 'F', 'Y', 'N') AS FAST_PO_YN , PR.PR_SEQ , PR.RD_DATE , CASE WHEN PODT.PROCESS_TYPE = '0' THEN ( SELECT MAX(DS_DATE) FROM ICOMPORS WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND DS_DATE = PODT.DS_DATE AND STATUS != 'D' ) ELSE (SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS != 'D') END AS CD_DATE , F_GET_PR_STTS(PR.BUYER, PR.PR_NO, PR.PR_SEQ , 1) AS STATUS_TEXT , (DECODE(PODT.PROCESS_TYPE,'0', (SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <>'D'), (SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D')) ) AS INVOICE_DATE , IVHD.PARCEL_COM_CODE , IVHD.PARCEL_INV_NO , PR.ADD_USER_TEL , (SELECT MAX(TARGET) FROM ICOMTRGW WHERE COM_CODE = PR.BUYER AND DOC_NAME = 'PR' AND KEY_1 = PR.PR_NO) AS GW_NO , (SELECT USER_NAME_ENG FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_NAME_ENG , (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_EMAIL , DECODE(PODT.PROCESS_TYPE, '0', IVHD.PARCEL_INV_NO, WMS.DELIVERY_NO) AS PARCEL_INFO , (SELECT MAX(CODE) FROM ICOMCOD2 WHERE TYPE = 'NOGR' AND COMPANY_CODE = PODT.BUYER AND FLAG = 'Y') AS GR_LOCK_MONTH , PR.CHANGE_DATE AS PR_CHANGE_DATE , POHD.PO_REMARK AS PH_REMARK , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'Z014' AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_NAME , IV.DELIVERY_DATE AS DELIVERY_DATE FROM ICOMPOHD POHD, ICOMPODT PODT ,ICOMPRDT PR , ICOMIVDT IV, WMSIVDT WMS, KEP_BUYER_FLAG BUYER, ICOMIVHD IVHD WHERE 1=1
AND PODT.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND PODT.BUYER = #{st_com_code}
