AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y'))
AND PR.ADD_USER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y'))
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y'))
AND PR.PURCHASER_ID IN ( SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_po_user_name}||'%' AND COM_CODE = #{st_com_code})
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND PODT.IV_QTY = PODT.DI_QTY
AND PODT.IV_QTY <> PODT.DI_QTY
AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.STATUS <> 'D' AND PODT.ITEM_QTY <> NVL(PODT.GR_QTY, 0) AND PODT.BUYER = IV.BUYER AND PODT.PO_NO = IV.PO_NO AND PODT.PO_SEQ = IV.PO_SEQ AND IV.STATUS <> 'D' AND IV.BUYER = IVHD.BUYER AND IV.INV_NO = IVHD.INV_NO AND PODT.BUYER = PR.BUYER AND PODT.PR_NO = PR.PR_NO AND PODT.PR_SEQ = PR.PR_SEQ AND PR.STATUS <> 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ = WMS.S_INV_SEQ(+) AND PODT.BUYER = BUYER.COM_CODE(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PODT.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) IS NOT NULL AND DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.GR_QTY,0), NVL(WMS.BUYER_GR_QTY,0)) <> DECODE(PODT.PROCESS_TYPE,'0',NVL(IV.INV_QTY,0), NVL(WMS.INV_QTY,0)) ORDER BY PO_NO, INV_NO, INV_SEQ ) S


/*selectBuyerWmGrWarehousingGrNo*/
SELECT DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0)
FROM ICOMSQMT
WHERE 
		COMPANY		= #{st_com_code} 
	AND DOC_TYPE 	= #{st_doc_type}

mapper.update:

/*insertBuyerWmGrWarehousingGrNo*/
INSERT INTO ICOMSQMT (
	  COMPANY
	, DOC_TYPE
	, YEAR
	, CUR_NO
) VALUES (
	  #{st_com_code}
	, #{st_doc_type}
	, TO_CHAR(SYSDATE,'YYYY')
	, 2
)


/*updateBuyerWmGrWarehousingGrNo*/
UPDATE ICOMSQMT 
SET 
	  YEAR   = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'), YEAR, TO_CHAR(SYSDATE,'YYYY'))
	, CUR_NO = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'),CUR_NO+1,1)
WHERE 
		COMPANY  = #{st_com_code} 
	AND DOC_TYPE = #{st_doc_type}


/*updateBuyerWmGrWarehousingPrdt*/
UPDATE ICOMPRDT
SET
	REF_PR_NO = #{gr_ref_pr_no}  -- 2024.02.02 관리번호 통일을 위해 REF_PR_NO 추가
WHERE
	(BUYER, PR_NO, PR_SEQ) IN 
	(
		SELECT BUYER, PR_NO, PR_SEQ 
		FROM ICOMPODT 
		WHERE	BUYER 	= #{buyer}
			AND SELLER  = #{seller}
			AND PO_NO   = #{po_no}
			AND PO_SEQ  = #{po_seq}
			AND STATUS != 'D'
			AND ITEM_QTY >= (NVL(GR_QTY,0) + ${gr_qty})
	)


/*updateBuyerWmGrWarehousingPodt*/
UPDATE ICOMPODT
SET
	GR_QTY = NVL(GR_QTY,0) + ${gr_qty},
	REF_PR_NO = #{gr_ref_pr_no}
WHERE
		BUYER 	= #{buyer}
	AND SELLER  = #{seller}
	AND PO_NO   = #{po_no}
	AND PO_SEQ  = #{po_seq}
	AND STATUS != 'D'
	AND ITEM_QTY >= (NVL(GR_QTY,0) + ${gr_qty})

mapper.select:

/*selectBuyerWmGrWarehousingProcessInfo*/
SELECT 
	  HD.PROCESS_TYPE
	, DECODE(PO.PROCESS_TYPE, '2', PO.WAREHOUSE_CODE, HD.AGENT) AS WAREHOUSE_CODE
FROM ICOMPODT PO, ICOMPOHD HD
WHERE
		PO.BUYER 	= #{buyer}
	AND PO.PO_NO 	= #{po_no}
	AND PO.PO_SEQ 	= #{po_seq}
	AND PO.BUYER 	= HD.BUYER
	AND PO.PO_NO 	= HD.PO_NO
	AND PO.STATUS <> 'D'
	AND HD.STATUS <> 'D'

mapper.update:

/*updateBuyerWmGrWarehousingIvdt*/
UPDATE ICOMIVDT A 
SET
	 A.GR_QTY = NVL(A.GR_QTY,0) + ${gr_qty}
	,A.REF_PR_NO = #{gr_ref_pr_no} -- 관리번호 통일을 위해 REF_PR_NO 추가 24.02.02 
WHERE 
		A.BUYER		= #{buyer}
	AND A.SELLER	= #{seller}
	AND A.INV_NO	= #{inv_no}
	AND A.INV_SEQ	= #{inv_seq}
	AND A.STATUS   != 'D'
	AND A.INV_QTY	= (NVL(A.GR_QTY,0) + ${gr_qty})


/*updateBuyerWmGrWarehousingIvhd*/
UPDATE ICOMIVHD
SET
	GR_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
WHERE 
		BUYER	= #{buyer}
	AND SELLER  = #{seller}
	AND INV_NO  = #{inv_no}
	AND STATUS != 'D'


/*updateBuyerWmGrWarehousingIvdt1*/
UPDATE WMSIVDT A 
SET
	  A.BUYER_GR_QTY = NVL(A.BUYER_GR_QTY,0) + ${gr_qty}
	, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
	, REF_PR_NO = #{gr_ref_pr_no}  -- 2024.02.02 관리번호 통일을 위해 REF_PR_NO 추가
WHERE 
		A.BUYER  = #{buyer}
	AND A.WAREHOUSE_CODE = DECODE(A.PROCESS_TYPE, '2', #{warehouse_code}, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='HUB' AND CODE = #{warehouse_code}))
	AND A.SELLER   = #{seller}
	AND A.INV_NO   = #{inv_no}
	AND A.INV_SEQ  = #{inv_seq}
	AND A.STATUS  != 'D'


/*updateBuyerWmGrWarehousingIvdt2*/
UPDATE ICOMIVDT A 
SET
	A.REF_PR_NO = #{gr_ref_pr_no} -- 관리번호 통일을 위해 REF_PR_NO 추가 24.02.02 
WHERE 
		A.BUYER 	= #{buyer}
	AND A.SELLER	= #{seller}
	AND A.PO_NO		= #{po_no}
	AND A.PO_SEQ	= #{po_seq}
	AND A.STATUS	!= 'D'

mapper.select:

/*selectBuyerWmGrWarehousingCarStockCheck*/
SELECT COUNT(1) AS CNT
FROM CAR_STOCK CAR
WHERE CAR.BUYER = #{buyer}
AND CAR.BUYER_ITEM_NO = #{buyer_item_no}

