/*insertBuyerWmGrWarehousingCarStock*/
INSERT INTO CAR_STOCK (
	BUYER
	,BUYER_ITEM_NO
	,BYIT_COMORG_CODE
	,GR_QTY
	,IV_QTY
	,ADD_USER_ID
	,ADD_DATE
	,CHANGE_USER_ID
	,CHANGE_DATE
	,STATUS
