	,0
	,#{user_id}
	,SYSDATE
	,#{user_id}
	,SYSDATE
	,'C'
)


/*updateBuyerWmGrWarehousingCarStockAdd*/
UPDATE CAR_STOCK SET
GR_QTY = (GR_QTY+#{gr_qty})
,CHANGE_USER_ID = #{user_id}
,CHANGE_DATE = SYSDATE
